  "inlineSchema": "generator client_billing {\n  provider = \"prisma-client-js\"\n  output   = \"./generated/billing\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nmodel Invoice {\n  id             String        @id\n  invoiceNumber  String        @unique\n  pelangganId    String\n  issueDate      DateTime      @default(now())\n  dueDate        DateTime\n  status         InvoiceStatus @default(DRAFT)\n  subtotal       BigInt        @default(0)\n  taxAmount      BigInt        @default(0)\n  discountAmount BigInt        @default(0)\n  totalAmount    BigInt        @default(0)\n  paidAmount     BigInt        @default(0)\n  notes          String?\n  terms          String?\n  sentAt         DateTime?\n  paidAt         DateTime?\n  createdBy      String?\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime\n  siteId         String?\n  invoiceItem    InvoiceItem[]\n  payment        Payment[]\n\n  @@index([dueDate])\n  @@index([invoiceNumber])\n  @@index([issueDate])\n  @@index([pelangganId])\n  @@index([status])\n  @@index([siteId])\n}\n\nmodel InvoiceItem {\n  id          String   @id\n  invoiceId   String\n  description String\n  quantity    Int      @default(1)\n  unitPrice   BigInt\n  totalPrice  BigInt\n  itemType    ItemType @default(SERVICE)\n  invoice     Invoice  @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n\n  @@index([invoiceId])\n}\n\nmodel Payment {\n  id              String                @id\n  invoiceId       String?\n  pelangganId     String\n  amount          BigInt\n  paymentDate     DateTime\n  paymentMethod   PaymentMethod\n  reference       String?\n  notes           String?\n  verifiedBy      String?\n  verifiedAt      DateTime?\n  createdAt       DateTime              @default(now())\n  updatedAt       DateTime\n  invoice         Invoice?              @relation(fields: [invoiceId], references: [id])\n  accountId       String?\n  gatewayStatus   GatewayPaymentStatus?\n  gatewayProvider String?\n  transactionId   String?\n  paymentUrl      String?\n  expiresAt       DateTime?\n\n  unmatchedMutationId String?            @unique\n  unmatchedMutation   UnmatchedMutation? @relation(fields: [unmatchedMutationId], references: [id])\n  receiptUrl          String?\n\n  @@index([invoiceId])\n  @@index([paymentDate])\n  @@index([pelangganId])\n  @@index([gatewayStatus])\n  @@index([transactionId])\n}\n\nmodel PaymentGatewayConfig {\n  id           String    @id\n  provider     String    @unique\n  providerName String\n  isEnabled    Boolean   @default(false)\n  isProduction Boolean   @default(false)\n  priority     Int       @default(0)\n  apiKey       String?\n  apiSecret    String?\n  clientKey    String?\n  merchantId   String?\n  webhookUrl   String?\n  callbackUrl  String?\n  settings     Json?\n  lastTestedAt DateTime?\n  testStatus   String?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime\n  createdBy    String?\n\n  @@index([isEnabled])\n  @@index([priority])\n  @@index([provider])\n}\n\nmodel UnmatchedMutation {\n  id            String   @id @default(uuid())\n  provider      String   @default(\"MOOTA\")\n  transactionId String?  @unique // Mutation ID from provider\n  amount        Decimal  @db.Decimal(19, 2)\n  description   String?\n  type          String? // CR/DB\n  date          DateTime // Date from provider\n  bankId        String? // Bank identifier\n  rawPayload    Json? // Store exact webhook payload\n\n  status           UnmatchedStatus @default(PENDING)\n  resolvedAt       DateTime?\n  resolvedById     String?\n  matchedInvoiceId String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  payment Payment? // Relation to the established payment if resolved\n\n  @@index([status])\n  @@index([provider])\n  @@index([amount])\n}\n\nenum UnmatchedStatus {\n  PENDING\n  RESOLVED\n  IGNORED\n}\n\n// Transksi dan Transaksi Kategori sengaja dihapus per Rencana Refactoring \n\nmodel MixRadiusInvoice {\n  id            String    @id @default(cuid())\n  invoiceNumber String    @unique\n  mixRadiusId   String? // The internal ID from MixRadius\n  username      String\n  fullName      String?\n  ownerName     String?\n  planName      String?\n  amount        Decimal   @db.Decimal(19, 2)\n  status        String // PAID, UNPAID, etc.\n  paymentMethod String?\n  issuedDate    DateTime // derived from renewed_on or created_on\n  dueDate       DateTime? // derived or calculated\n  expiredOn     DateTime?\n  syncedAt      DateTime  @default(now())\n\n  @@index([status])\n  @@index([username])\n  @@index([ownerName])\n  @@index([dueDate])\n  @@map(\"mix_radius_invoices\")\n}\n\nenum InvoiceStatus {\n  DRAFT\n  SENT\n  OVERDUE\n  PAID\n  PARTIAL_PAID\n  CANCELLED\n}\n\nenum ItemType {\n  SERVICE\n  PRODUCT\n  SETUP_FEE\n  MONTHLY_FEE\n  ONE_TIME_FEE\n  OTHER\n}\n\nenum PaymentMethod {\n  CASH\n  BANK_TRANSFER\n  E_WALLET\n  CREDIT_CARD\n  DEBIT_CARD\n  CHECK\n  OTHER\n}\n\nenum Status {\n  AKTIF\n  NONAKTIF\n  MAINTENANCE\n  ISOLIR\n  DISMANTLE\n}\n\nenum TransactionType {\n  INCOME\n  EXPENSE\n}\n\nenum ExpenseType {\n  OPERATIONAL // Opex\n  CAPITAL // Capex\n  OTHER\n}\n\nenum PaymentStatus {\n  UNPAID\n  PARTIAL\n  PAID\n}\n\nenum GatewayPaymentStatus {\n  PENDING\n  PAID\n  FAILED\n  EXPIRED\n  CANCELLED\n  REFUNDED\n}\n\nmodel MixRadiusCustomer {\n  id           String    @id\n  mixRadiusId  String    @unique\n  username     String    @unique\n  fullName     String?\n  address      String?\n  phoneNumber  String?\n  planName     String?\n  status       String?\n  ownerName    String?\n  expiredOn    DateTime?\n  lastSyncedAt DateTime  @default(now())\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@map(\"mix_radius_customers\")\n}\n\nmodel MixRadiusOwnerGroup {\n  id        String   @id @default(uuid())\n  name      String\n  owners    String[]\n  siteId    String? // Soft-relation to Sites in main DB\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Note: expenses and rabProjects are managed via repository layer (soft-relations)\n\n  @@index([siteId])\n  @@map(\"mix_radius_owner_groups\")\n}\n\nmodel MixRadiusInvestorSite {\n  id        String   @id @default(uuid())\n  name      String // Nama Site Investor (misal: \"Proyek Cimenyan - Investor A\")\n  owners    String[] // Daftar owner MixRadius yang pendapatannya masuk ke site ini\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@map(\"mix_radius_investor_sites\")\n}\n\nmodel MixRadiusConfig {\n  id           String    @id @default(uuid())\n  name         String    @default(\"Default\")\n  apiUrl       String\n  username     String\n  password     String\n  apiKey       String\n  isDefault    Boolean   @default(false)\n  lastSyncedAt DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n\n  @@map(\"mix_radius_configs\")\n}\n"
